/**
 * strings.js — the translation tables.
 *
 * Interface only. See i18n.js for why flavour text stays in English.
 *
 * Keys are dotted and grouped by where they appear. Keep them descriptive
 * (`settings.quality.low`) rather than positional (`label7`) — a translator
 * working without the game in front of them has only the key for context.
 *
 * {braces} mark interpolated values. They must survive translation intact, so
 * they are always a bare token, never split across words. There is a test that
 * checks every language carries the same tokens as English.
 */

